// (the settings-door law) — so every timed poll here NUDGES with a
// harmless mouse-move to keep the loop ticking, as a held phone would.
const nudge = (i) => send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: 200 + (i % 5), y: 420 + (i % 7) });
await tap(pts.scry);
let tapped = false;
for (let i = 0; i < 16 && !tapped; i++) { tapped = ((await ev('(window.__f5scry||{}).tapped | 0')) >= 1); if (!tapped) await sleep(400); }
const b1s = await ev("(()=>{const b=game.scene.getScene('battle');return b.board.map(s=>s?s.ch:'·').join('')})()");
ok('a REAL tap on SCRY fires the scry itself — the board redeals (beat 2)', tapped && b1s !== b0, tapped ? 'redealt' : 'no tap seen');
let down = null;
for (let i = 0; i < 24 && !down; i++) { await nudge(i); const d = await ev('(window.__f5scry||{}).down || null'); if (d) down = d; else await sleep(400); }
ok('THE COST IS SHOWN: the count steps down before the raised pill (' + cnt0 + ' → ' + (cnt0 - 1) + ') — after the reveal\'s own slow rise (900 + 700 ms)', !!down && down[0] === cnt0 && down[1] === cnt0 - 1, String(down));
await tap(pts.cast);   // a tap BEFORE the floor — the reveal must hold
await sleep(500);
const rv = await ev("(()=>{const b=game.scene.getScene('battle');const s=window.__f5scry||{};const show=b.children.list.filter(o=>o.active&&o.getData&&o.getData('f5scryshow'));return {show:show.length,d:show[0]?show[0].depth:null,n:show[0]?show[0].list.length:0,pill:[b.strikeGlow.depth,b.strikeRib.depth,b.strikeT.depth].join('/'),text:b.strikeT.text,lifted:s.lifted|0,released:s.released||null,cost:s.cost|0,costP:(window.__f5prompt||{}).scryCost|0}})()");
ok('THE REVEAL HOLDS (the slowed beat, card 03): the old reading struck through, the new one hot, the cost line beneath — five parts at 950 over the raised pill reading ' + (cnt0 - 1) + '; a tap before the floor did NOT lift it', rv.show === 1 && rv.d === 950 && rv.n === 5 && rv.pill === '901/902/903' && rv.text.includes(' ' + (cnt0 - 1) + ' ') && rv.lifted === 0 && !rv.released, JSON.stringify(rv));
ok('…then SAID: the cost line speaks (once, like every lesson)', rv.cost === 1 && rv.costP === 1);
// past the floor (1.4 s from the step), a REAL tap lets go — the 1.4s needs real
// accumulated game time: BURST the nudges (a woken headless clock pays ~one
// clamped frame per input event)
for (let i = 0; i < 4; i++) { for (let k = 0; k < 6; k++) await nudge(i * 6 + k); await sleep(250); }
await tap(pts.cast);
let lifted = false;
for (let i = 0; i < 30 && !lifted; i++) {
  for (let k = 0; k < 6; k++) await nudge(i * 6 + k);
  lifted = ((await ev('(window.__f5scry||{}).lifted | 0')) >= 1);
  if (!lifted) await sleep(250);
}
const rel = JSON.parse(await ev("JSON.stringify([(window.__f5scry||{}).released||null,(window.__f5scry||{}).holdMs|0])"));
ok('THE GATE LIFTS (beat 4) — a REAL tap past the floor let go (held ≥ 1.4 s from the step)', lifted && rel[0] === 'tap' && rel[1] >= 1400, JSON.stringify(rel));
const after = await ev("(()=>{const b=game.scene.getScene('battle');return [b.f5ScryGate===null,b.scryB.depth,b.scryT.depth,b.strikeT.depth,b.strikeRib.depth,b.strikeGlow.depth,SS.prof.f5scry|0,b.strikeT.text.includes(' " + (cnt0 - 1) + " ')?1:0].join('|')})()");
ok('every depth goes home; the pill tells the new truth; the lesson is written', after === 'true|0|0|0|0|0|1|1', after);
await sleep(1200);   // the redeal's bounce settles before the resume taps
// NORMAL PLAY RESUMES — the same real fingers that were refused now answer
await tap(pts.tile);
let selGrew = false;
for (let i = 0; i < 10 && !selGrew; i++) { selGrew = ((await ev("game.scene.getScene('battle').sel.length")) === 1); if (!selGrew) await sleep(400); }
ok('tiles ANSWER again after the lift (a real tap selects)', selGrew);
await ev('window.__f5refusal=null');
await tap(pts.cast);
let bounced = false;
for (let i = 0; i < 10 && !bounced; i++) { bounced = ((await ev('String(window.__f5refusal)')) === 'home'); if (!bounced) await sleep(400); }
ok('CAST ANSWERS again after the lift (a real tap runs the one-letter bounce)', bounced && await ev("game.scene.getScene('battle').sel.length === 0"));
// THE ONCE LAW — a later stall only glints; the hand is never taken twice
await sleep(900);   // the bounce settles home
const glint0 = await ev('window.__f5glint | 0');
await ev("(()=>{const b=game.scene.getScene('battle');b.f5Glinted=false;b.f5LastTap=b.time.now-11000;return 1})()");
let reglint = false;
for (let i = 0; i < 16 && !reglint; i++) { await nudge(i + 90); reglint = ((await ev('window.__f5glint | 0')) > glint0); if (!reglint) await sleep(500); }
ok('a later stall only GLINTS — the lesson never takes the hand twice', reglint && ((await ev('(window.__f5scry||{}).armed | 0')) === 1) && await ev("game.scene.getScene('battle').f5ScryGate === null"));
ok('…and the ribbon never spoke OVER the lesson (the gate owned the voice)', (await ev('(window.__f5prompt||{}).scry | 0')) === pr0, 'ribbon count ' + await ev('(window.__f5prompt||{}).scry | 0') + ' (was ' + pr0 + ')');
ok('zero exceptions through the whole lesson', errs.length === 0, errs.slice(0, 2).join(' | '));

/* ======== §3c THE CLEAN REFRESH — the fix itself (F5-FIX1-01) ======== */
console.log('— §3c THE CLEAN REFRESH: a player refresh is a true first open —');
// the night is standing (held fight, stats, marks). Put a sentinel beside
// them, then refresh like a thumb would — Page.reload, NO survive flag
await ev("localStorage.setItem('beta3.f5sentinel', 'standing')");
ok('the night stands before the refresh (held fight in the pocket)', await ev("localStorage.getItem('beta3.quickck') !== null"));
errs.length = 0;
await send('Page.reload', {});
await sleep(2500);
let wiped = false;
for (let i = 0; i < 40 && !wiped; i++) { wiped = await ev("localStorage.getItem('beta3.f5sentinel') === null && localStorage.getItem('beta3.quickck') === null && localStorage.getItem('beta3.stat') === null"); if (!wiped) await sleep(1000); }
ok('PULL-TO-REFRESH WIPES THE NIGHT: sentinel, held fight and stat all gone', wiped);
let virgin = false;
for (let i = 0; i < 40 && !virgin; i++) { virgin = (await ev('typeof SS !== "undefined" && SS.prof ? SS.prof.ftue : null')) === 0; if (!virgin) await sleep(1000); }
ok('the FTUE gate is OPEN again — the refresh made a stranger (ftue 0 = owed)', virgin);
ok('the lit sky is empty again', (await ev("typeof ssF5LitList === 'function' ? ssF5LitList().length : null")) === 0);
let start = null; // the tutorial at its VERY start: the lure asks, and waits
for (let i = 0; i < 180 && !start; i++) { const st = await ev("window.__ssftue ? window.__ssftue.state : null"); if (st === 'lure') start = st; if (!start) await sleep(1000); }
ok('the tutorial stands at its very start — the lure asks again, at the title', start === 'lure' && await ev("(()=>{try{const h=game.scene.getScene('home');return !!(h.f5TitleFx&&h.f5TitleFx.t.active)&&(-h.cameras.main.scrollY/h.sky.T)>=0.9}catch(e){return false}})()"));
ok('zero exceptions through the clean refresh', errs.length === 0, errs.slice(0, 2).join(' | '));

/* ================= §4 the reset door ================= */
console.log('— §4 the reset door (redundant now, still honored) —');
await ev("localStorage.setItem('beta3.f5sentinel', 'reset-me')");
await ev('window.__f5survive()');   // even CARRIED, an explicit reset wins
await go(BASE + '?reset=1');
await sleep(4000);
ok('?reset=1 wiped the night — even over a survive flag (reset out-ranks)', await ev("localStorage.getItem('beta3.f5sentinel') === null && localStorage.getItem('beta3.stat') === null"));
ok('?reset=1 scrubbed itself from the URL', await ev("!location.search.includes('reset')"), await ev('location.search'));
let reborn = false;
for (let i = 0; i < 20 && !reborn; i++) { reborn = (await ev('typeof SS !== "undefined" && SS.prof ? SS.prof.ftue : null')) === 0; if (!reborn) await sleep(1000); }
ok('the first open is VIRGIN again (ftue gate re-open)', reborn);
ok('zero exceptions on the reborn open', errs.length === 0, errs.slice(0, 2).join(' | '));

/* ================= §5 ?art=0 — the procedural fallback, as live ================= */
console.log('— §5 ?art=0: the procedural night of old, as the live game keeps it —');
await go(BASE + '?reset=1&art=0');
let lure0 = false;
for (let i = 0; i < 180 && !lure0; i++) { lure0 = (await ev("window.__ssftue ? window.__ssftue.state : null")) === 'lure'; if (!lure0) await sleep(1000); }
ok('?art=0: the title stands and the lure asks (the fallback still opens straight)', lure0);
const a0 = await ev("(()=>{try{const h=game.scene.getScene('home');const L=ssLayout(h);" + BASEKEY + "const kids=h.children.list;const tdots=kids.filter(o=>o.type==='Image'&&!o.parentContainer&&base(o)==='dot'&&o.scrollFactorY<1);return {art:h.sky.art,tex:h.textures.exists('nightskyart'),plate:!!kids.find(o=>o.type==='Image'&&base(o)==='nightskyart'),word:h.f5TitleFx?base(h.f5TitleFx.t):null,tdots:tdots.length,maxS:+Math.max(...tdots.map(o=>o.scaleX)).toFixed(3),cap:+(0.24*L.s).toFixed(3),glow:h.f5TitleFx?+h.f5TitleFx.glow.alpha.toFixed(3):null}}catch(e){return {err:e.message}}})()");
ok('?art=0: no plate, the live-text wordmark (title@en), the full 110/75/48 tiers past the cap — the procedural night, byte for byte', !!a0 && a0.art === false && !a0.tex && !a0.plate && a0.word === 'title@en' && a0.tdots === 233 && a0.maxS > a0.cap, JSON.stringify(a0));
ok('zero exceptions on the ?art=0 open', errs.length === 0, errs.slice(0, 2).join(' | '));

/* ======== §6 the live game's own frames — the reference the first5 night is judged against ======== */
console.log("— §6 THE PIXEL LAW: the live game on the same server, its zenith + its title shade, the first5 frames judged against them —");
const LIVE = BASE.replace(/first5\/index\.html(\?.*)?$/, 'index.html');
await send('Network.enable', {});
await send('Network.setBlockedURLs', { urls: ['*firebaseio.com*', '*firebasedatabase.app*', '*firebase*', '*gstatic.com*'] });
await go(LIVE + '?fps=0&ftue=0');
let liveHome = false;
for (let i = 0; i < 60 && !liveHome; i++) { await poke(i); liveHome = (await ev("(()=>{try{const h=game.scene.getScene('home');return !!(h&&h.sys.isActive()&&h.sky&&h.introPlaying===false)}catch(e){return false}})()")) === true; if (!liveHome) await sleep(1000); }
const liveArt = await ev("(()=>{try{const h=game.scene.getScene('home');return {build:typeof BUILD==='string'?BUILD:null,ready:SSART.ready,night:!!SSART.img.nightsky,title:!!SSART.img.title,art:h.sky.art===true,tex:h.textures.exists('nightskyart')}}catch(e){return {err:e.message}}})()");
ok('the live game boots on this server and stands on its painted plate (a real reference, not a mock)', liveHome && !!liveArt && liveArt.ready && liveArt.night && liveArt.title && liveArt.art && liveArt.tex, JSON.stringify(liveArt));
// the frame the rise lands on — the home at the zenith, the grain hidden as the
// rise hides it, the meadow chrome dark (the sky-stays reference, exactly)
await ev("(()=>{try{const h=game.scene.getScene('home');h.sky.grain.setVisible(false);for(const o of h.uiItems)if(o&&o.active){h.tweens.killTweensOf(o);o.setAlpha(0)}h.sky.setP(1,0);return 1}catch(e){return 'err:'+e.message}})()");
await poke(1); await sleep(500); await poke(2);
const shotZ = await send('Page.captureScreenshot', { format: 'png' });
if (shotZ && shotZ.data) writeFileSync('tools/shots-straight/live-zenith.png', Buffer.from(shotZ.data, 'base64'));
// the title's own shade: the same world at p 0.92 with the painted word standing
// where the intro lands it (playIntro's seat, the halo at its whisper)
await ev("(()=>{try{const h=game.scene.getScene('home');const l=ssLayout(h);h.sky.setP(0.92,0);const tk=ssTitleTex(h);const ts=Math.min(1,384/tk.w);h.add.image(l.W/2,l.H*0.4,tk.key).setDisplaySize(l.u(tk.w*ts),l.u(tk.h*ts)).setScrollFactor(0).setDepth(610);h.add.image(l.W/2,l.H*0.4,'glowbig').setScale(l.u(2.1)).setTint(0xf3e5b4).setBlendMode('ADD').setScrollFactor(0).setDepth(605).setAlpha(0.18*0.55);return 1}catch(e){return 'err:'+e.message}})()");
await poke(3); await sleep(500); await poke(4);
const shotS = await send('Page.captureScreenshot', { format: 'png' });
if (shotS && shotS.data) writeFileSync('tools/shots-straight/live-title-shade.png', Buffer.from(shotS.data, 'base64'));
ok('two live references on file: live-zenith.png (the frame the fight blends FROM) + live-title-shade.png (the title at the zenith shade)', !!(shotZ && shotZ.data && shotS && shotS.data));
console.log('  i  live-page exceptions (the live game, not first5 — informational): ' + (errs.length ? errs.slice(0, 2).join(' | ') : 'none'));
try {
  const dpr = (vp && vp[2]) || 3;
  const F = readPNG('tools/shots-straight/first-fight.png'), Z = readPNG('tools/shots-straight/live-zenith.png');
  const T = readPNG('tools/shots-straight/title-night.png'), Sh = readPNG('tools/shots-straight/live-title-shade.png');
  const cssH = F.h / dpr;
  const strips = (x, y) => (x < 28 * dpr || x >= F.w - 28 * dpr) && y >= 110 * dpr && y < Math.min(700, cssH - 10) * dpr;
  const jF = judge(F, Z, strips, 6);
  ok("THE PIXEL LAW — the first fight stands on the frame the live rise lands on: the outer sky strips (rows 110–" + Math.min(700, Math.round(cssH - 10)) + ") agree ≥ 95% within ±6", jF.pct >= 95, JSON.stringify(jF));
  const jT = judge(T, Sh, () => true, 8);
  ok("…the title night IS the live game's title at the zenith shade: the full frame agrees ≥ 95% within ±8 (the lure's firefly and the random tiers are the rest)", jT.pct >= 95, JSON.stringify(jT));
  if (titleBounds) {
    const [bx, by, bw, bh] = titleBounds.map((v) => v * dpr);
    const jW = judge(T, Sh, (x, y) => x >= bx && x < bx + bw && y >= by && y < by + bh, 8);
    ok('…the painted wordmark itself — the same art at the same seat: its band agrees ≥ 90% within ±8', jW.pct >= 90, JSON.stringify(jW));
  } else ok('the title bounds were read at the lure (the wordmark band can be judged)', false);
  const jOld = judge(T, F, strips, 6);
  console.log('  i  (for scale: the title night vs the first fight on the same strips — different frames — ' + jOld.pct + '% within ±6, mean |Δ| ' + jOld.mean + ')');
} catch (e) { ok('the pixel judge ran (png decode + compare)', false, String(e && e.message)); }

console.log('\n' + pass + ' passed · ' + fail + ' failed');
kids.forEach((k) => { try { k.kill(); } catch (e) { } });
process.exit(fail ? 1 : 0);
